def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute sum of floor divisions
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

scripts.gcd_multiple:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Compute GCD of all values
    result = values[0]
    for value in values[1:]:
        result = math.gcd(result, value)

    return float(result)

scripts.luhn_checksum:
def solve(inputs: dict) -> float:
    n = str(inputs['N'])

    # Read digits from right to left
    digits = [int(d) for d in n]
    digits.reverse()

    total = 0
    for i, digit in enumerate(digits):
        if i % 2 == 1:  # Every second digit (0-indexed, so position 1, 3, 5, ...)
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += digit

    return float(total)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count pairs where earlier entry > later entry
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

